package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.util.UUID;import jakarta.persistence.*;import com.yeyamo_mobile.api.notification_service.domain.NotificationChannel;
@Entity@Table(name="notification_templates")public class TemplateEntity{@Id private UUID id;@Column(name="event_type",nullable=false,length=120)private String eventType;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private NotificationChannel channel;@Column(nullable=false,length=10)private String locale;@Column(name="subject_template",length=300)private String subjectTemplate;@Column(name="body_template",nullable=false,columnDefinition="TEXT")private String bodyTemplate;@Column(nullable=false)private boolean active;public String getSubjectTemplate(){return subjectTemplate;}public String getBodyTemplate(){return bodyTemplate;}}
